<script setup>
import { computed, onUnmounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { useCollection, useCurrentUser, useFirestore } from 'vuefire'
import { collection, orderBy, query, where } from 'firebase/firestore'

const router = useRouter(); const db = useFirestore(); const user = useCurrentUser(); const timerSection = ref(null)
const tasks = useCollection(computed(() => query(collection(db,'Recordatorios'),where('user','==',user.value?.uid || ''),orderBy('name','asc'))))
const allTasks = computed(() => tasks.value || []); const completed = computed(() => allTasks.value.filter((task)=>task.done).length); const pending = computed(() => allTasks.value.filter((task)=>!task.done).length); const overdue = computed(() => allTasks.value.filter((task)=>task.dueAt && new Date(task.dueAt)<new Date() && !task.done).length); const rate = computed(() => allTasks.value.length ? Math.round(completed.value/allTasks.value.length*100) : 0)
const seconds = ref(25*60); const running = ref(false); const sessions = ref(Number(localStorage.getItem('lumina-focus-sessions') || 0)); let timer
const time = computed(() => `${String(Math.floor(seconds.value/60)).padStart(2,'0')}:${String(seconds.value%60).padStart(2,'0')}`)
function toggleTimer(){ running.value=!running.value; if(running.value) timer=window.setInterval(()=>{ if(seconds.value) seconds.value--; else finishSession() },1000); else window.clearInterval(timer) }
function finishSession(){ sessions.value++; localStorage.setItem('lumina-focus-sessions',sessions.value); resetTimer() }
function resetTimer(){ window.clearInterval(timer); running.value=false; seconds.value=25*60 }
function scrollToTimer(){ timerSection.value?.scrollIntoView({ behavior: 'smooth', block: 'center' }) }
function exportSummary(){ const data={date:new Date().toISOString(),completed:completed.value,pending:pending.value,overdue:overdue.value,completionRate:rate.value,focusSessions:sessions.value}; const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}); const url=URL.createObjectURL(blob); const link=document.createElement('a'); link.href=url; link.download='lumina-focus-resumen.json'; link.click(); URL.revokeObjectURL(url) }
onUnmounted(()=>window.clearInterval(timer))
</script>

<template>
<main class="focus-page"><header class="focus-header"><button class="back-button" @click="router.push('/Recordatorios')">← Volver a recordatorios</button><span class="focus-badge">✦ FOCUS PREMIUM</span></header>
<section class="focus-welcome"><span class="eyebrow">TU CENTRO DE PRODUCTIVIDAD</span><h1>Entiende tu progreso.<br><em>Mejora tu concentración.</em></h1><p>Focus convierte tus recordatorios en información sencilla para que sepas qué hacer, cuándo hacerlo y cuánto estás avanzando.</p><div class="welcome-actions"><button class="btn-primary" @click="scrollToTimer">Empezar una sesión ↗</button><button class="btn-ghost" @click="exportSummary">Descargar mi resumen</button></div></section>
<section class="how-focus"><article><b>01</b><strong>Observa</strong><span>Mira tus métricas sin complicaciones.</span></article><article><b>02</b><strong>Concéntrate</strong><span>Trabaja en sesiones cortas y realistas.</span></article><article><b>03</b><strong>Avanza</strong><span>Convierte el progreso en un hábito.</span></article></section>
<section class="metric-grid"><article><small>Tareas completadas</small><strong>{{ completed }}</strong><span>de {{ allTasks.length }} totales</span></article><article><small>Ahora mismo</small><strong>{{ pending }}</strong><span>tareas pendientes</span></article><article><small>Rendimiento</small><strong>{{ rate }}%</strong><span>tasa de finalización</span></article><article><small>Atención</small><strong>{{ overdue }}</strong><span>tareas vencidas</span></article></section>
<section class="focus-columns"><article class="focus-panel chart-panel"><div class="panel-title"><div><span class="eyebrow">RESUMEN RÁPIDO</span><h2>Tu progreso actual</h2></div><span class="rate-pill">{{ rate }}%</span></div><div class="progress-track"><i :style="{width:`${rate}%`}"></i></div><p v-if="rate">Has completado {{ completed }} tarea{{ completed===1?'':'s' }}. Sigue con una más para mantener el ritmo.</p><p v-else>Aún no hay tareas completadas. El primer paso es elegir una tarea pequeña.</p><div class="mini-stats"><span><b>{{ sessions }}</b> sesiones Focus</span><span><b>{{ overdue }}</b> vencidas</span></div></article><article ref="timerSection" class="focus-panel focus-timer"><span class="eyebrow">MODO CONCENTRACIÓN</span><h2>25 minutos para una sola tarea</h2><div class="timer">{{ time }}</div><p>Trabaja sin interrupciones y descansa al terminar.</p><div class="timer-actions"><button class="btn-primary" @click="toggleTimer">{{ running?'Pausar sesión':'Comenzar sesión' }}</button><button class="btn-ghost" @click="resetTimer">Reiniciar</button></div></article></section>
<section class="features-premium"><div><span class="eyebrow">¿QUÉ APORTA FOCUS?</span><h2>Todo lo importante, explicado de un vistazo</h2></div><div class="feature-list"><article><b>◷</b><strong>Sesiones de enfoque</strong><p>Divide tu trabajo en bloques de 25 minutos para avanzar sin saturarte.</p></article><article><b>↗</b><strong>Progreso visible</strong><p>Comprueba cuántas tareas completas y qué áreas necesitan atención.</p></article><article><b>✓</b><strong>Resumen descargable</strong><p>Guarda tus métricas en un archivo para revisar tu evolución.</p></article></div><button class="btn-ghost" @click="exportSummary">Descargar resumen en JSON ↧</button></section>
</main>
</template>

<style scoped>
.focus-page{margin:auto;max-width:1080px;padding:2rem 1.5rem 5rem}.focus-header{align-items:center;display:flex;justify-content:space-between}.back-button{background:transparent;border:1px solid var(--line);border-radius:6px;color:var(--muted);font-size:.72rem;padding:.6rem .85rem}.back-button:hover{border-color:var(--teal);color:var(--teal)}.focus-badge{color:var(--teal);font-size:.62rem;font-weight:700;letter-spacing:.16em}.eyebrow{color:var(--teal);font-size:.62rem;font-weight:700;letter-spacing:.16em}.focus-welcome{margin:5rem auto 3rem;max-width:670px;text-align:center}.focus-welcome h1{font-size:clamp(2.2rem,5vw,4rem);line-height:1.04;margin:1rem 0}.focus-welcome h1 em{color:var(--teal);font-style:normal}.focus-welcome p{color:var(--muted);font-size:.9rem;line-height:1.7;margin:auto;max-width:560px}.welcome-actions{display:flex;gap:.6rem;justify-content:center;margin-top:1.5rem}.how-focus{display:grid;gap:1rem;grid-template-columns:repeat(3,1fr);margin:0 auto 1rem;max-width:850px}.how-focus article{background:rgba(24,211,154,.06);border:1px solid rgba(24,211,154,.2);border-radius:8px;padding:1rem}.how-focus b{color:var(--teal);font-size:.65rem}.how-focus strong,.how-focus span{display:block}.how-focus strong{font-size:.85rem;margin:.5rem 0 .2rem}.how-focus span{color:var(--muted);font-size:.68rem}.metric-grid{display:grid;gap:1rem;grid-template-columns:repeat(4,1fr);margin-top:1rem}.metric-grid article,.focus-panel,.features-premium{background:rgba(21,29,33,.92);border:1px solid var(--line);border-radius:10px;padding:1.25rem}.metric-grid small,.metric-grid span{color:var(--muted);display:block;font-size:.65rem}.metric-grid strong{display:block;font-family:'Space Grotesk',sans-serif;font-size:2rem;margin:.45rem 0}.focus-columns{display:grid;gap:1rem;grid-template-columns:1.1fr 1fr;margin-top:1rem}.panel-title{align-items:flex-start;display:flex;justify-content:space-between}.focus-panel h2,.features-premium h2{font-size:1.15rem;margin:.5rem 0}.rate-pill{background:rgba(24,211,154,.12);border-radius:5px;color:var(--teal);font-size:.8rem;padding:.35rem}.progress-track{background:#0b1114;border-radius:20px;height:10px;margin:2rem 0 1rem;overflow:hidden}.progress-track i{background:var(--teal);border-radius:20px;display:block;height:100%;transition:width .4s}.focus-panel p,.feature-list p{color:var(--muted);font-size:.73rem;line-height:1.6}.mini-stats{display:flex;gap:1rem;margin-top:1.5rem}.mini-stats span{border-left:1px solid var(--line);color:var(--muted);font-size:.65rem;padding-left:.7rem}.mini-stats b{color:var(--text);display:block;font-size:1rem}.focus-timer{text-align:center}.timer{color:var(--teal);font-family:'Space Grotesk',sans-serif;font-size:3.5rem;margin:1.5rem 0}.timer-actions{display:flex;gap:.5rem;justify-content:center}.timer-actions button{font-size:.7rem}.features-premium{margin-top:1rem}.feature-list{display:grid;gap:1rem;grid-template-columns:repeat(3,1fr);margin:1.5rem 0}.feature-list article{background:#10181c;border:1px solid var(--line);border-radius:7px;padding:1rem}.feature-list b{color:var(--teal);font-size:1.2rem}.feature-list strong{display:block;font-size:.8rem;margin:.7rem 0 .3rem}.features-premium>.btn-ghost{font-size:.7rem}@media(max-width:700px){.metric-grid{grid-template-columns:1fr 1fr}.focus-columns{grid-template-columns:1fr}.feature-list{grid-template-columns:1fr}.how-focus{grid-template-columns:1fr}.welcome-actions{align-items:stretch;flex-direction:column}}@media(max-width:450px){.metric-grid{grid-template-columns:1fr}.focus-header{align-items:flex-start;flex-direction:column;gap:1rem}}
</style>
